import java.util.*; class Solution { public double[] medianSlidingWindow(int[] nums, int k) { int n = nums.length; double[] result = new double[n - k + 1]; TreeSet<Integer> left = new TreeSet<>((a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b)); TreeSet<Integer> right = new TreeSet<>((a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b)); for (int i = 0; i < k; i++) { left.add(i); } for (int i = 0; i < k / 2; i++) { right.add(left.pollLast()); } for (int i = 0; ; i++) { if (k % 2 == 1) { result[i] = (double) nums[left.last()]; } else { result[i] = ((double) nums[left.last()] + (double) nums[right.first()]) / 2.0; } if (i + k == n) break; int out = i; int in = i + k; if (!left.remove(out)) { right.remove(out); } if (left.isEmpty() || nums[in] <= nums[left.last()]) { left.add(in); } else { right.add(in); } if (left.size() > (k + 1) / 2) { right.add(left.pollLast()); } else if (left.size() < (k + 1) / 2) { left.add(right.pollFirst()); } } return result; } }